        let (seccomp, no_new_privileges) = resolve_security_opts(&[], false).unwrap();
        assert_eq!(
            seccomp.unwrap(),
            oci_runtime_core::seccomp::filter_to_supported_syscalls(
                &oci_runtime_core::seccomp::default_profile()
            )
        );
